621	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
622	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
623	func authzCurrentStatus(a authzRec, now time.Time) string {
624		switch a.Status {
625		case "revoked":
626			return AuthRevoked
627		case "used":
628			return AuthUsed
629		}
630		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
631			return AuthExpired
632		}
633		return AuthActive
634	}
