677	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
678		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
679		// 仍可回放；改价则按请求号冲突拒绝。
680		b, _ := json.Marshal(struct {
681			Kind          string `json:"kind"`
682			AuthID        string `json:"auth_id"`
683			ItemID        string `json:"item_id"`
684			TrusteeID     string `json:"trustee_id"`
685			ToID          string `json:"to_id"`
686			ExpectedOwner string `json:"expected_owner"`
687			ExpectedVer   int64  `json:"expected_version"`
688			ExpiresAt     string `json:"expires_at"`
689			Price         int64  `json:"price,omitempty"`
690			Reason        string `json:"reason"`
691		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
692			req.ExpectedOwner, req.ExpectedVer,
693			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
694		return string(b)
695	}
696	
697	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
698	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
699	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
700	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
701	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
702	//
703	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
704	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
705	// 参数错误与引用不存在不占用请求号。
706	//
707	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
708	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
709	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
710	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
711	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
712	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
713	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
714	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
715	// 错误（首次重提不标回放），状态已满足请求则正常创建。
716	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
717		if err := req.validatePresent(); err != nil {
718			return CreateAuthorizationResult{}, err
719		}
720		r.mu.Lock()
721		defer r.mu.Unlock()
722		if err := r.checkOpen(); err != nil {
723			return CreateAuthorizationResult{}, err
724		}
725	
726		now := r.now()
727		key := requestKey(req.Operator, req.RequestID)
728		sig := createAuthzParamsSig(req)
729		if prev, ok := r.state.Requests[key]; ok {
730			return r.replayCreateAuthz(prev, sig)
731		}
732	
733		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
734			if !isValidationErr(bizErr) {
735				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
736				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
737				r.state.Requests[key] = request{
738					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
739					Params: sig, Rejected: true, Reason: errCode(bizErr),
740					AuthID: req.AuthID, ItemID: req.ItemID,
741				}
742				if err := r.commit(); err != nil {
743					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
744					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
745					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
746					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
747					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
748					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
749					// 为零、不标回放、结果中业务错误为空，error 保留实际
750					// 写入错误。
751					delete(r.state.Requests, key)
752					return CreateAuthorizationResult{}, err
753				}
754			}
755			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
756		}
757	
758		h := r.state.Holdings[req.ItemID]
759		a := authzRec{
760			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
761			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
762			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
763		}
764		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
765		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
766		// 一次成功保存都会把这份未保存的授权带进登记册。
767		prevAuthSeq := r.state.NextAuthSeq
768		prevEvents := len(r.state.AuthEvents)
769		r.state.Authzs[req.AuthID] = a
770		authSeq := prevAuthSeq + 1
771		r.state.NextAuthSeq = authSeq
772		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
773			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
774			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
775			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
776		})
777		r.state.Requests[key] = request{
778			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
779			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
780		}
781		if err := r.commit(); err != nil {
782			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
783			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
784			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
785			if _, ok := r.state.Requests[key]; ok {
786				delete(r.state.Requests, key)
787				delete(r.state.Authzs, req.AuthID)
788				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
789				r.state.NextAuthSeq = prevAuthSeq
790			}
791			return CreateAuthorizationResult{}, err
792		}
793		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
794	}
795	
796	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
797		h, ok := r.state.Holdings[req.ItemID]
798		if !ok {
799			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
800				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
801			}
802			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
803		}
804		op, ok := r.state.Accounts[req.Operator]
805		if !ok {
806			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
807		}
808		trustee, ok := r.state.Accounts[req.TrusteeID]
809		if !ok {
810			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
811		}
812		to, ok := r.state.Accounts[req.ToID]
813		if !ok {
814			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
815		}
816		if req.TrusteeID == req.Operator {
817			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
818		}
819		if req.ToID == req.Operator {
820			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
821		}
822		if !op.Active {
823			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
824		}
825		if !trustee.Active {
826			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
827		}
828		if !to.Active {
829			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
830		}
831		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
832		if _, exists := r.state.Authzs[req.AuthID]; exists {
833			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
834		}
835		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
836		if !req.ExpiresAt.After(now) {
837			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
838				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
839		}
840		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
841			req.Operator != h.OwnerID {
842			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
843				ErrConflict, req.ItemID, h.OwnerID, h.Version)
844		}
845		return nil
846	}
