871	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
872	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
873	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
874	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
875	// revoked）。请求号语义与其他操作一致。
876	//
877	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
878	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
879	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
880	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
881	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
882	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
883	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
884	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
885	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
886	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
887	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
888	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
889	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
890	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
891		missing := []string{}
892		if strings.TrimSpace(req.Operator) == "" {
893			missing = append(missing, "operator")
894		}
895		if strings.TrimSpace(req.Reason) == "" {
896			missing = append(missing, "reason")
897		}
898		if strings.TrimSpace(req.RequestID) == "" {
899			missing = append(missing, "request_id")
900		}
901		if strings.TrimSpace(req.AuthID) == "" {
902			missing = append(missing, "auth_id")
903		}
904		if len(missing) > 0 {
905			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
906				ErrInvalidArgument, strings.Join(missing, ", "))
907		}
908		r.mu.Lock()
909		defer r.mu.Unlock()
910		if err := r.checkOpen(); err != nil {
911			return RevokeAuthorizationResult{}, err
912		}
913	
914		now := r.now()
915		key := requestKey(req.Operator, req.RequestID)
916		sig := revokeAuthzParamsSig(req)
917		if prev, ok := r.state.Requests[key]; ok {
918			return r.replayRevokeAuthz(prev, sig)
919		}
920	
921		a, ok := r.state.Authzs[req.AuthID]
922		if !ok {
923			// 引用不存在不占用请求号。
924			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
925			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
926		}
927		if a.GranterID != req.Operator {
928			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
929				ErrForbidden, a.GranterID, req.AuthID)
930			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
931				return RevokeAuthorizationResult{}, err
932			}
933			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
934		}
935		switch authzCurrentStatus(a, now) {
936		case AuthUsed:
937			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
938			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
939				return RevokeAuthorizationResult{}, err
940			}
941			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
942		case AuthRevoked:
943			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
944			// 相同请求重放回放同一结果。
945			r.state.Requests[key] = request{
946				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
947				Params: sig, AuthID: req.AuthID,
948			}
949			if err := r.commit(); err != nil {
950				return RevokeAuthorizationResult{}, err
951			}
952			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
953		}
954	
955		from := AuthActive
956		if authzCurrentStatus(a, now) == AuthExpired {
957			from = AuthExpired
958		}
959		a.Status = "revoked"
960		a.RevokedAt = now
961		r.state.Authzs[req.AuthID] = a
962		authSeq := r.state.NextAuthSeq + 1
963		r.state.NextAuthSeq = authSeq
964		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
965			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
966			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
967			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
968		})
969		r.state.Requests[key] = request{
970			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
971			Params: sig, AuthID: req.AuthID,
972		}
973		if err := r.commit(); err != nil {
974			return RevokeAuthorizationResult{}, err
975		}
976		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
977	}
