1135	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1136		a, ok := r.state.Authzs[req.AuthID]
1137		if !ok {
1138			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1139		}
1140		op, ok := r.state.Accounts[req.Operator]
1141		if !ok {
1142			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1143		}
1144		granter, gOk := r.state.Accounts[a.GranterID]
1145		to, tOk := r.state.Accounts[a.ToID]
1146		if req.Operator != a.TrusteeID {
1147			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1148				ErrForbidden, req.Operator, req.AuthID)
1149		}
1150		if !gOk {
1151			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1152		}
1153		if !tOk {
1154			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1155		}
1156		if !op.Active {
1157			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1158		}
1159		if !granter.Active {
1160			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1161		}
1162		if !to.Active {
1163			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1164		}
1165		switch authzCurrentStatus(a, now) {
1166		case AuthRevoked:
1167			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1168		case AuthExpired:
1169			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1170		case AuthUsed:
1171			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1172		}
1173		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1174		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1175		h, ok := r.state.Holdings[a.ItemID]
1176		if !ok {
1177			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1178		}
1179		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1180			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1181				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1182		}
1183		return nil
1184	}
1185	
1186	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1187		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1188			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1189				ErrRequestConflict, prev.Operator, prev.RequestID)
1190		}
1191		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1192			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1193		if prev.Rejected {
1194			res.Err = codeErr(prev.Reason)
1195			return res, res.Err
1196		}
1197		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1198		// 原价款与应付明细，不重复计入。
1199		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1200		return res, nil
1201	}
1202	
1203	// ---- 授权查询 ----
1204	
1205	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1206	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1207	// 到期但尚未终结的授权返回 AuthExpired。
1208	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1209		r.mu.Lock()
1210		defer r.mu.Unlock()
1211		if err := r.checkOpen(); err != nil {
1212			return Authorization{}, err
1213		}
1214		a, ok := r.state.Authzs[authID]
1215		if !ok {
1216			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1217		}
1218		return Authorization{
1219			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1220			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1221			Status:    authzCurrentStatus(a, r.now()),
1222			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1223			RevokedAt: a.RevokedAt,
1224		}, nil
1225	}
1226	
1227	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1228	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1229	// 不存在时返回包裹 ErrNotFound 的错误。
1230	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1231		r.mu.Lock()
1232		defer r.mu.Unlock()
1233		if err := r.checkOpen(); err != nil {
1234			return nil, err
1235		}
1236		if _, ok := r.state.Items[itemID]; !ok {
1237			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1238		}
1239		out := make([]AuthorizationEvent, 0)
1240		for _, e := range r.state.AuthEvents {
1241			if e.ItemID != itemID {
1242				continue
1243			}
1244			out = append(out, AuthorizationEvent{
1245				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1246				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1247				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1248				OccurredAt: e.OccurredAt,
1249			})
1250		}
1251		return out, nil
1252	}
1253	
1254	// ---- 查询 ----
1255	
1256	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1257	func (r *Registry) GetItem(id string) (Item, error) {
1258		r.mu.Lock()
1259		defer r.mu.Unlock()
1260		if err := r.checkOpen(); err != nil {
1261			return Item{}, err
1262		}
1263		it, ok := r.state.Items[id]
1264		if !ok {
1265			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1266		}
1267		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1268			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1269	}
1270	
1271	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1272	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1273		r.mu.Lock()
1274		defer r.mu.Unlock()
1275		if err := r.checkOpen(); err != nil {
1276			return Holding{}, err
1277		}
1278		h, ok := r.state.Holdings[itemID]
1279		if !ok {
1280			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1281		}
1282		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1283	}
1284	
1285	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1286	// ErrNotFound 的错误；停用账户仍可正常查询。
1287	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1288		r.mu.Lock()
1289		defer r.mu.Unlock()
1290		if err := r.checkOpen(); err != nil {
1291			return nil, err
1292		}
1293		if _, ok := r.state.Accounts[accountID]; !ok {
1294			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1295		}
1296		out := make([]Holding, 0)
1297		for _, h := range r.state.Holdings {
1298			if h.OwnerID == accountID {
1299				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1300			}
1301		}
1302		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1303		return out, nil
1304	}
1305	
1306	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1307	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1308	// 返回包裹 ErrNotFound 的错误。
1309	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1310		r.mu.Lock()
1311		defer r.mu.Unlock()
1312		if err := r.checkOpen(); err != nil {
1313			return nil, err
1314		}
1315		if _, ok := r.state.Items[itemID]; !ok {
1316			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1317		}
1318		out := make([]HistoryEntry, 0)
1319		for _, e := range r.state.History {
1320			if e.ItemID != itemID {
1321				continue
1322			}
1323			out = append(out, HistoryEntry{
1324				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1325				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1326				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1327			})
1328		}
1329		return out, nil
1330	}
1331	
1332	// ---- 幂等辅助 ----
1333	
1334	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1335	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1336	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1337	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1338	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1339	func requestKey(operator, requestID string) string {
1340		b, _ := json.Marshal([2]string{operator, requestID})
1341		return string(b)
1342	}
1343	
1344	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1345	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1346	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1347	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1348	// 并回放。
1349	func isValidationErr(err error) bool {
1350		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1351	}
1352	
1353	var errCodes = map[error]string{
1354		ErrNotFound:             "not_found",
1355		ErrAlreadyExists:        "already_exists",
1356		ErrAccountInactive:      "account_inactive",
1357		ErrSeriesSealed:         "series_sealed",
1358		ErrConflict:             "conflict",
1359		ErrSameAccount:          "same_account",
1360		ErrForbidden:            "forbidden",
1361		ErrAuthorizationRevoked: "authorization_revoked",
1362		ErrAuthorizationExpired: "authorization_expired",
1363		ErrAuthorizationUsed:    "authorization_used",
1364		ErrRoyaltyFrozen:        "royalty_frozen",
1365		ErrSplitIntentRejected:  "split_intent_rejected",
1366		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1367		ErrSplitIntentInvalid:   "split_intent_invalid",
1368		ErrSplitIntentExpired:   "split_intent_expired",
1369		ErrSplitAnswered:        "split_answered",
1370	}
1371	
1372	var codeErrs = map[string]error{
1373		"not_found":              ErrNotFound,
1374		"already_exists":         ErrAlreadyExists,
1375		"account_inactive":       ErrAccountInactive,
1376		"series_sealed":          ErrSeriesSealed,
1377		"conflict":               ErrConflict,
1378		"same_account":           ErrSameAccount,
1379		"forbidden":              ErrForbidden,
1380		"authorization_revoked":  ErrAuthorizationRevoked,
1381		"authorization_expired":  ErrAuthorizationExpired,
1382		"authorization_used":     ErrAuthorizationUsed,
1383		"royalty_frozen":         ErrRoyaltyFrozen,
1384		"split_intent_rejected":  ErrSplitIntentRejected,
1385		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1386		"split_intent_invalid":   ErrSplitIntentInvalid,
1387		"split_intent_expired":   ErrSplitIntentExpired,
1388		"split_answered":         ErrSplitAnswered,
1389	}
1390	
1391	func errCode(err error) string {
1392		for sentinel, code := range errCodes {
1393			if errors.Is(err, sentinel) {
1394				return code
1395			}
1396		}
1397		return "rejected"
1398	}
1399	
1400	func codeErr(code string) error {
1401		if e, ok := codeErrs[code]; ok {
1402			return e
1403		}
1404		return errors.New("registry: 请求曾被拒绝")
1405	}
1406

