173		assertTransferSuccessStillPending(t, r, "i1", req.RequestID)
174	
175		// 保存条件未恢复、磁盘仍不可读时再次提交同一请求：仍失败在保存上，
176		// 不能把上次未保存的成功当成已保存结果回放。
177		res, err = r.Transfer(req)
178		assertTransferSaveFailureEmpty(t, res, err)
179		assertTransferSuccessStillPending(t, r, "i1", req.RequestID)
180	
181		// 恢复正常读写；先让一次无关操作成功保存，不能夹带这笔未保存的转让。
182		if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
183			t.Fatal(err)
184		}
185		restoreBatchSave(t, r)
186		if err := r.RegisterAccount("eve", "路人"); err != nil {
187			t.Fatalf("无关操作应能成功保存: %v", err)
188		}
189		assertTransferSuccessStillPending(t, r, "i1", req.RequestID)
190	
191		// 用原操作者、请求号、原因和全部参数重提：条件仍满足，完整完成一次，
192		// 不标回放，版本只加一次，序号紧接已有历史（8）。
193		res, err = r.Transfer(req)
194		if err != nil {
195			t.Fatalf("恢复后重提应完整执行一次: %v", err)
196		}
197		wantPayables := []RoyaltyPayable{
198			{AccountID: "carol", Rate: 1000, Amount: 1000},
199			{AccountID: "dave", Rate: 500, Amount: 500},
200		}
201		if res.Replayed || res.Err != nil || res.ItemID != "i1" ||
202			res.FromID != "bob" || res.ToID != "carol" || res.Version != 2 || res.TxSeq != 8 ||
203			res.Price != 10000 || res.Remainder != 8500 || !reflect.DeepEqual(res.Payables, wantPayables) {
204			t.Fatalf("重提结果异常: %+v", res)
205		}
206		h, _ := r.GetHolding("i1")
207		if h.OwnerID != "carol" || h.Version != 2 {
208			t.Fatalf("重提成功后 i1 持有 = %+v", h)
209		}
210		if hist, _ := r.History("i1"); len(hist) != 2 || hist[1].Seq != 8 ||
211			hist[1].RequestID != req.RequestID || hist[1].FromID != "bob" || hist[1].ToID != "carol" {
212			t.Fatalf("重提成功后 i1 历史异常: %+v", hist)
213		}
214		tr, _ := r.TransferRoyalty(8)
215		if tr.ItemID != "i1" || tr.Price != 10000 || tr.Remainder != 8500 || tr.OwnerID != "bob" ||
216			!reflect.DeepEqual(tr.Payables, wantPayables) {
217			t.Fatalf("本次转让版税记录异常: %+v", tr)
218		}
219		if r.state.NextSeq != 8 {
220			t.Fatalf("NextSeq = %d, want 8", r.state.NextSeq)
221		}
222	
223		// 只有此次成功保存后再提相同内容，才返回这一笔已保存的结果（回放），
224		// 不再第二次换人、不重复计金额。
225		replay, err := r.Transfer(req)
226		if err != nil || !replay.Replayed || replay.Version != 2 || replay.TxSeq != 8 ||
227			replay.Price != 10000 || replay.Remainder != 8500 {
228			t.Fatalf("成功保存后再提应回放已保存结果: %+v, err %v", replay, err)
229		}
230		h, _ = r.GetHolding("i1")
231		if h.OwnerID != "carol" || h.Version != 2 {
232			t.Fatalf("回放不应再次改变持有: %+v", h)
233		}
234		if hist, _ := r.History("i1"); len(hist) != 2 {
235			t.Fatalf("回放不应新增历史: %+v", hist)
236		}
237		if carolPay, _ := r.PayablesOf("carol"); len(carolPay) != 2 {
238			t.Fatalf("回放不应重复计入应付: %+v", carolPay)
239		}
240	}
241	
242	// TestTransferSuccessSaveFailureReadableSameRegistry 覆盖：写入失败但原数据
243	// 仍可正常读取（commit 据磁盘内容重建状态）时，得到相同的失败结果与状态
244	// 保障——同一登记册上转让从未发生；恢复后原请求重提完整执行一次。
245	func TestTransferSuccessSaveFailureReadableSameRegistry(t *testing.T) {
246		r := mustCreate(t, tempDir(t))
247		seedTransferSuccessWorld(t, r)
248		req := xferSaveReq("rt-ok-r", "i1", "bob", 1, "carol", 10000)
249	
250		// 只阻断写入，不破坏数据文件：rename 之前失败，原快照完好可读。
251		blockBatchSave(t, r)
252		res, err := r.Transfer(req)
253		assertTransferSaveFailureEmpty(t, res, err)
254		assertTransferSuccessStillPending(t, r, "i1", req.RequestID)
255	
256		restoreBatchSave(t, r)
257		res, err = r.Transfer(req)
258		if err != nil || res.Replayed || res.ItemID != "i1" ||
259			res.FromID != "bob" || res.ToID != "carol" || res.Version != 2 || res.TxSeq != 8 {
260			t.Fatalf("可读磁盘失败恢复后重提应完整执行一次: %+v, err %v", res, err)
261		}
262		// 成功保存后再提才回放。
263		replay, err := r.Transfer(req)
264		if err != nil || !replay.Replayed || replay.TxSeq != 8 {
265			t.Fatalf("成功后再提应回放: %+v, err %v", replay, err)
266		}
267	}
268	
269	// TestTransferSuccessSaveFailureRetryAfterReopen 覆盖磁盘视角：成功转让保存
270	// 失败（原数据可读）后关闭重开，看到的仍是转让前状态；恢复保存后用原请求
271	// 重提完整执行一次，而不是回放一个从未保存的成功。
272	func TestTransferSuccessSaveFailureRetryAfterReopen(t *testing.T) {
273		dir := tempDir(t)
274		r := mustCreate(t, dir)
275		t.Cleanup(func() { _ = r.Close() })
276		seedTransferSuccessWorld(t, r)
277		req := xferSaveReq("rt-ok-reopen", "i1", "bob", 1, "carol", 10000)
278	
279		blockBatchSave(t, r)
280		res, err := r.Transfer(req)
281		assertTransferSaveFailureEmpty(t, res, err)
282	
283		// 数据文件从未被替换：正常关闭并重新打开仍读到转让前状态。
284		if err := r.Close(); err != nil {
285			t.Fatal(err)
286		}
287		r2, err := Open(dir)
288		if err != nil {
289			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
290		}
291		t.Cleanup(func() { _ = r2.Close() })
292		assertTransferSuccessStillPending(t, r2, "i1", req.RequestID)
293	
294		restoreBatchSave(t, r2)
295		res2, err := r2.Transfer(req)
296		if err != nil || res2.Replayed || res2.TxSeq != 8 || res2.Version != 2 ||
297			res2.FromID != "bob" || res2.ToID != "carol" {
298			t.Fatalf("重开后重提应完整执行一次: %+v, err %v", res2, err)
299		}
300		replay, err := r2.Transfer(req)
301		if err != nil || !replay.Replayed || replay.TxSeq != 8 {
302			t.Fatalf("成功后再提应回放: %+v, err %v", replay, err)
303		}
304	}
305	
306	// TestTransferSuccessSaveFailureRetryConflict 覆盖：恢复期间藏品被另一笔合法
307	// 转让转出后，原请求必须按现有版本冲突规则拒绝，不能回放先前未保存的成功。
308	func TestTransferSuccessSaveFailureRetryConflict(t *testing.T) {
309		r := mustCreate(t, tempDir(t))
310		seedTransferSuccessWorld(t, r)
311		req := xferSaveReq("rt-ok-c", "i1", "bob", 1, "carol", 10000)
312	
313		orig, err := os.ReadFile(dataFile(r.dir))
314		if err != nil {
315			t.Fatal(err)
316		}
317		blockBatchSave(t, r)
318		if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
319			t.Fatal(err)
320		}
321		res, err := r.Transfer(req)
322		assertTransferSaveFailureEmpty(t, res, err)
323		assertTransferSuccessStillPending(t, r, "i1", req.RequestID)
324	
325		// 恢复读写后，bob 先把 i1 合法转让给 alice：i1 变为 alice 版本 2（序号 8）。
326		if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
327			t.Fatal(err)
328		}
329		restoreBatchSave(t, r)
330		if _, err := r.Transfer(TransferRequest{
331			Operator: "bob", Reason: "恢复期间的合法转让", RequestID: "rt-intervene", ItemID: "i1",
332			ExpectedOwner: "bob", ExpectedVer: 1, ToID: "alice", Price: 5000,
333		}); err != nil {
334			t.Fatal(err)
335		}
336	
337		// 原请求（仍期望 bob 版本 1）按当前持有状态应被版本冲突拒绝，不是回放
338		// 那次未保存的成功；拒绝不改变持有。
339		res, err = r.Transfer(req)
340		if !errors.Is(err, ErrConflict) {
341			t.Fatalf("藏品已转出后原请求应按版本冲突拒绝: %v", err)
342		}
343		if res.Replayed || res.ItemID != "i1" || !errors.Is(res.Err, ErrConflict) ||
344			res.Version != 0 || res.TxSeq != 0 {
345			t.Fatalf("冲突拒绝的结果异常: %+v", res)
346		}
347		h, _ := r.GetHolding("i1")
348		if h.OwnerID != "alice" || h.Version != 2 {
349			t.Fatalf("冲突拒绝不应改变持有: %+v", h)
350		}
351		// 这是一次新保存的状态类拒绝（占用请求号），但没有新增转让或序号。
352		prev, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]
353		if !ok || !prev.Rejected || prev.TxSeq != 0 {
354			t.Fatalf("冲突拒绝应已登记为拒绝结果: %+v", prev)
355		}
356		if r.state.NextSeq != 8 {
357			t.Fatalf("冲突拒绝不应消耗历史序号: NextSeq=%d", r.state.NextSeq)
358		}
359		if _, err := r.TransferRoyalty(9); !errors.Is(err, ErrNotFound) {
360			t.Fatalf("冲突拒绝不应产生版税记录: %v", err)
361		}
362	
363		// 此后原样重提回放这条已保存的冲突拒绝（仍不执行转让）。
364		res, err = r.Transfer(req)
365		if !errors.Is(err, ErrConflict) || !res.Replayed || !errors.Is(res.Err, ErrConflict) {
366			t.Fatalf("冲突拒绝保存后再提应回放该拒绝: %+v, err %v", res, err)
367		}
368		h, _ = r.GetHolding("i1")
369		if h.OwnerID != "alice" || h.Version != 2 {
370			t.Fatalf("回放冲突拒绝不应改变持有: %+v", h)
371		}
372	}
373	
374	// TestTransferSuccessSaveFailureZeroPriceNoRoyalty 覆盖零价款与无版税系列的
375	// 转让在保存失败时同样不留任何应付或计算记录，恢复后重提沿用零价款/无版税
376	// 的既有行为成功一次。
377	func TestTransferSuccessSaveFailureZeroPriceNoRoyalty(t *testing.T) {
378		cases := []struct {
379			name        string
380			item        string
381			wantPayable []RoyaltyPayable // 重提成功后期望的应付明细（零金额也保留）
382		}{
383			{
384				name:        "no_royalty_series_zero_price",
385				item:        "i4", // s3 无版税
386				wantPayable: []RoyaltyPayable{},
387			},
388			{
389				name: "royalty_series_zero_price",
390				item: "i1", // s1：carol 10% + dave 5%，零价款 => 零金额明细仍保留
391				wantPayable: []RoyaltyPayable{
392					{AccountID: "carol", Rate: 1000, Amount: 0},
393					{AccountID: "dave", Rate: 500, Amount: 0},
394				},
395			},
396		}
397		for _, tc := range cases {
398			t.Run(tc.name, func(t *testing.T) {
399				r := mustCreate(t, tempDir(t))
400				seedTransferSuccessWorld(t, r)
401				req := xferSaveReq("rt-zero-"+tc.item, tc.item, "bob", 1, "alice", 0)
402	
403				orig, err := os.ReadFile(dataFile(r.dir))
404				if err != nil {
405					t.Fatal(err)
406				}
407				blockBatchSave(t, r)
408				if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
409					t.Fatal(err)
410				}
411				res, err := r.Transfer(req)
412				assertTransferSaveFailureEmpty(t, res, err)
413	
414				// 未保存的零价款转让同样不留下序号 8 记录、不新增任何应付。
415				h, _ := r.GetHolding(tc.item)
416				if h.OwnerID != "bob" || h.Version != 1 {
417					t.Fatalf("保存失败后 %s 持有被改变: %+v", tc.item, h)
418				}
419				if _, err := r.TransferRoyalty(8); !errors.Is(err, ErrNotFound) {
420					t.Fatalf("未保存转让不应留下版税记录: %v", err)
421				}
422				if carolPay, _ := r.PayablesOf("carol"); len(carolPay) != 1 || carolPay[0].TxSeq != 7 {
423					t.Fatalf("未保存转让不应新增应付：%+v", carolPay)
424				}
425				if r.state.NextSeq != 7 {
426					t.Fatalf("NextSeq = %d, want 7", r.state.NextSeq)
427				}
428	
429				// 恢复后重提：零价款/无版税转让完整成功一次，余款为 0。
430				if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
431					t.Fatal(err)
432				}
433				restoreBatchSave(t, r)
434				res, err = r.Transfer(req)
435				if err != nil || res.Replayed || res.ItemID != tc.item ||
436					res.Version != 2 || res.TxSeq != 8 || res.Price != 0 || res.Remainder != 0 {
437					t.Fatalf("重提结果异常: %+v, err %v", res, err)
438				}
439				if !reflect.DeepEqual(res.Payables, tc.wantPayable) {
440					t.Fatalf("%s 重提应付 = %+v, want %+v", tc.item, res.Payables, tc.wantPayable)
441				}
442				tr, _ := r.TransferRoyalty(8)
443				if tr.ItemID != tc.item || tr.Price != 0 || tr.Remainder != 0 || tr.OwnerID != "bob" ||
444					!reflect.DeepEqual(tr.Payables, tc.wantPayable) {
445					t.Fatalf("重提版税记录异常: %+v", tr)
446				}
447	
448				// 再提回放，不第二次执行。
449				replay, err := r.Transfer(req)
450				if err != nil || !replay.Replayed || replay.TxSeq != 8 {
451					t.Fatalf("成功后再提应回放: %+v, err %v", replay, err)
452				}
453				if hist, _ := r.History(tc.item); len(hist) != 2 {
454					t.Fatalf("回放不应新增历史: %+v", hist)
455				}
456			})
457		}
458	}
