package registry

import (
	"errors"
	"os"
	"reflect"
	"testing"
)

// 本文件为整批转让补充"保存失败"场景的回归保障：业务检查全部通过后，
// 在本次内容原子替换已保存数据之前写入失败（原登记册仍可正常读取）时，
// 整批必须整体失败、不留任何部分转让，请求号与历史序号都不被消耗；
// 保存条件恢复后用完全相同的请求号、原因与条目重提，必须完整执行一次，
// 而不是回放一个实际没有保存的成功结果或报请求号冲突。
//
// 失败注入方式：在临时文件路径 .registry.json.tmp 上预先建一个目录，
// save 在 OpenFile 阶段即以 EISDIR 失败——失败发生在 rename 替换
// registry.json 之前，原快照完好可读；删除该目录即恢复保存条件。该方式
// 不依赖文件权限（root 也生效），也不会触碰原数据文件。

// batchSaveFailureReq 是各用例共用的整批请求：至少两件、接收账户互不相同，
// 且包含带版税规则的藏品（i1/i3 属 s1：carol 10% + dave 5%；i2 属 s2：
// carol 100%）。各件期望持有人 bob、版本 1。
func batchSaveFailureReq() TransferBatchRequest {
	return tbtReq("rb-fail",
		tbtEntry("i1", "carol", 1, 10000),
		tbtEntry("i2", "dave", 1, 333),
		tbtEntry("i3", "alice", 1, 500),
	)
}

// seedBatchSaveFailureWorld 建立一个已经存在成功转让与应付记录的登记册：
// setupBatchTransferWorld 发行 i1..i5（历史序号 1..5）后，再由 alice 发行
// i6（s1，序号 6）给 bob，并由 bob 以 10000 分把 i6 转让给 alice（序号 7）。
// 因此失败发生前最后一条历史序号是 7；carol/dave 各有一条序号 7 的应付
// （1000/500），余款 8500 归 bob。清单外藏品 i4（bob，版本 1）、i5
// （carol，版本 1）与已易手的 i6（alice，版本 2）用于核对失败不外溢。
func seedBatchSaveFailureWorld(t *testing.T, r *Registry) {
	t.Helper()
	setupBatchTransferWorld(t, r)
	if _, err := r.Issue(IssueRequest{
		Operator: "alice", Reason: "首发", RequestID: "ri-i6",
		ItemID: "i6", SeriesID: "s1", BatchNo: "b1",
		Metadata: "元-i6", HolderID: "bob",
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Transfer(TransferRequest{
		Operator: "bob", Reason: "先存一笔成功转让", RequestID: "rt-prior", ItemID: "i6",
		ExpectedOwner: "bob", ExpectedVer: 1, ToID: "alice", Price: 10000,
	}); err != nil {
		t.Fatal(err)
	}
}

// blockBatchSave 让下一次 commit 的写入在替换数据文件之前确定性失败。
func blockBatchSave(t *testing.T, r *Registry) {
	t.Helper()
	if err := os.MkdirAll(tempFile(r.dir), dirMode); err != nil {
		t.Fatalf("注入保存失败: %v", err)
	}
}

// restoreBatchSave 恢复保存条件：移除占据临时文件路径的目录。
func restoreBatchSave(t *testing.T, r *Registry) {
	t.Helper()
	if err := os.RemoveAll(tempFile(r.dir)); err != nil {
		t.Fatalf("恢复保存条件: %v", err)
	}
}

// businessSentinels 是保存错误必须有别于业务拒绝的哨兵集合。
var businessSentinels = []error{
	ErrConflict, ErrAccountInactive, ErrSameAccount, ErrForbidden,
	ErrRequestConflict, ErrInvalidArgument, ErrNotFound, ErrSeriesSealed,
}

// assertSaveFailureError 确认返回的是保存错误而非任何业务拒绝。
func assertSaveFailureError(t *testing.T, err error) {
	t.Helper()

package registry

import "errors"

// 错误哨兵。业务拒绝与参数错误使用包裹这些哨兵的错误，调用方可用
// errors.Is 判定；返回结果中的 Err 字段同样包裹这些哨兵。
var (
	// ErrNotFound 表示查询或引用的账户、系列或藏品不存在。
	ErrNotFound = errors.New("registry: 对象不存在")

	// ErrAlreadyExists 表示账户、系列或藏品编号已被占用。
	ErrAlreadyExists = errors.New("registry: 对象已存在")

	// ErrAccountInactive 表示账户已停用，不能参与新的发行或转让。
	ErrAccountInactive = errors.New("registry: 账户已停用")

	// ErrSeriesSealed 表示系列已封存，不能继续发行；封存不可撤销。
	ErrSeriesSealed = errors.New("registry: 系列已封存")

	// ErrConflict 表示乐观并发冲突：藏品持有人或期望版本与当前状态不符。
	ErrConflict = errors.New("registry: 持有人或版本不符，转让被拒绝")

	// ErrSameAccount 表示转让的发起人与接收人相同。
	ErrSameAccount = errors.New("registry: 转让发起人与接收人不能相同")

	// ErrForbidden 表示操作者无权执行该操作（例如非系列创建账户发行或封存、
	// 非授权人撤销授权、非受托人发起代转）。
	ErrForbidden = errors.New("registry: 操作者无权执行该操作")

	// ErrAuthorizationRevoked 表示代转授权已被授权人撤销，不能再用于代转。
	ErrAuthorizationRevoked = errors.New("registry: 授权已撤销")

	// ErrAuthorizationExpired 表示代转授权已过绝对到期时间，从到期时间点
	// 起不可再使用。
	ErrAuthorizationExpired = errors.New("registry: 授权已过期")

	// ErrAuthorizationUsed 表示一次性代转授权已被使用（或对已使用的授权
	// 请求撤销）。
	ErrAuthorizationUsed = errors.New("registry: 授权已使用")

	// ErrRoyaltyFrozen 表示系列已成功发行首件藏品，版税规则已固定，
	// 不能再设置或清空。
	ErrRoyaltyFrozen = errors.New("registry: 版税规则已固定")

	// ErrSplitIntentRejected 表示拆分意向已被参与账户拒绝，不再接受答复，
	// 也不能撤回。
	ErrSplitIntentRejected = errors.New("registry: 拆分意向已拒绝")

	// ErrSplitIntentWithdrawn 表示拆分意向已被发起人撤回，不再接受答复。
	ErrSplitIntentWithdrawn = errors.New("registry: 拆分意向已撤回")

	// ErrSplitIntentInvalid 表示拆分意向已失效：藏品持有版本已变化，或
	// 发起人、任一参与账户已停用；失效不可恢复。
	ErrSplitIntentInvalid = errors.New("registry: 拆分意向已失效")

	// ErrSplitIntentExpired 表示拆分意向已过绝对到期时间，从到期时间点
	// 起不再接受答复或撤回。
	ErrSplitIntentExpired = errors.New("registry: 拆分意向已过期")

	// ErrSplitAnswered 表示参与账户已作出不同答复，不能改答。
	ErrSplitAnswered = errors.New("registry: 已作出不同答复，不能改答")

	// ErrRequestConflict 表示请求号已被同一操作者使用，但本次业务参数不同。
	ErrRequestConflict = errors.New("registry: 请求号冲突")

	// ErrInvalidArgument 表示必填内容缺失或参数不合法。
	ErrInvalidArgument = errors.New("registry: 参数不合法")

	// ErrCorrupt 表示登记册数据已存在但无法读取或解析。
	ErrCorrupt = errors.New("registry: 登记册数据无法读取")

	// ErrLocked 表示登记册正被另一个进程以独占方式使用。
	ErrLocked = errors.New("registry: 登记册已被占用")
)

